        }

        Permit permit = permits.findById(request.permitId())
                .orElseThrow(() -> ApiException.notFound("申请单不存在: " + request.permitId()));
        if (permit.status() != PermitStatus.APPROVED) {
            throw ApiException.unprocessable("NOT_APPROVED",
