                        .content("{\"requestId\":\"\",\"zoneId\":1,\"applicant\":\"张三\","
                                + "\"plannedBlastTime\":\"2026-09-26T08:00:00Z\",\"chargePerDelay\":10}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.code").value("VALIDATION_FAILED"));
    }
}

